fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let pct: i32 = t % 101;
    host::display::clear(0x000000);
    let bx: i32 = 20;
    let bw: i32 = w - 40;
    host::display::fill_rect(bx - 2, h / 2 - 14, bw + 4, 2, 0xffffff);
    host::display::fill_rect(bx - 2, h / 2 + 12, bw + 4, 2, 0xffffff);
    host::display::fill_rect(bx - 2, h / 2 - 14, 2, 28, 0xffffff);
    host::display::fill_rect(bx + bw, h / 2 - 14, 2, 28, 0xffffff);
    host::display::fill_rect(bx, h / 2 - 10, bw * pct / 100, 20, 0x00ff00);
    host::display::draw_number(bx, h / 2 + 24, pct, 0xffffff, 2);
    host::display::draw_string(bx + 40, h / 2 + 24, "%", 0xffffff, 2);
    if pct < 100 && (t / 15) % 2 == 0 {
        host::display::draw_string(bx, h / 2 - 40, "LOADING", 0x808080, 2);
    }
    host::display::present();
}
